{
  "world_id": "wld_hollow_exchequer",
  "name": "The Hollow Exchequer",
  "description": "The Hollow Exchequer is the bureaucratic underworld of a mythic age. Death is an accounting problem, not a mystery. Every mortal soul arrives as a ledger entry, and its worth is tallied across columns of deed, debt, and devotion before the final weighing decides where it rests. The dead cannot return to life. Only their accounts move, shifting between columns, counting-houses, and the memory of the living. The tone is wry and solemn: clerks bicker over ink grades and stamp precedence while each decision holds an eternity. A junior scribe discovers a mortal soul entered in the wrong ledger column. She must carry the correction upward through five counting-houses, each with its own pride, procedures, and appetite for convenient errors, before the soul is weighed and the mistake becomes permanent.",
  "locations": [
    {
      "id": "loc_gate_of_entries",
      "name": "The Gate of Entries",
      "description": "A cavernous receiving hall where newly dead souls are named, numbered, and given a provisional ledger line. Queues of the departed shuffle between brass rails while tally-clerks call out surnames in flat, practiced voices."
    },
    {
      "id": "loc_scriptorium_of_ash",
      "name": "The Scriptorium of Ash",
      "description": "A low, soot-dark hall where junior scribes copy each soul's first tally using ink distilled from funeral pyres. It is the starting point of the scribe's journey and the place where the miscolumned entry was first made."
    },
    {
      "id": "loc_counting_house_of_debts",
      "name": "The Counting-House of Debts",
      "description": "A towering stack of galleries where every unpaid promise, borrowed favor, and broken oath is weighed against the dead. Its auditors distrust corrections on principle, since a correction implies they once erred."
    },
    {
      "id": "loc_archive_of_quiet_names",
      "name": "The Archive of Quiet Names",
      "description": "A silent, endless library of sealed ledgers, kept by archivists who speak only in whispered cross-references. Old records here can prove or disprove any correction, if the scribe can persuade the keepers to open the right drawer."
    },
    {
      "id": "loc_hall_of_the_scales",
      "name": "The Hall of the Scales",
      "description": "The final chamber, where the Weigher sets a soul's finished ledger against a single grey feather. What is entered here is never amended, so the ruling carries absolute weight."
    }
  ],
  "factions": [
    {
      "id": "fac_guild_of_scribes",
      "name": "The Guild of Scribes",
      "description": "The copyists and tally-clerks who record every soul. They are underpaid, overworked, and fiercely proud of a clean hand. Junior scribes carry the blame for errors that senior ones sign off on.",
      "location_ids": ["loc_scriptorium_of_ash", "loc_gate_of_entries"]
    },
    {
      "id": "fac_auditors_of_debt",
      "name": "The Auditors of Debt",
      "description": "Stern assessors who believe every soul owes something and that the books should always lean toward the house. They guard their columns jealously and resist any change that lowers a balance.",
      "location_ids": ["loc_counting_house_of_debts"]
    },
    {
      "id": "fac_keepers_of_names",
      "name": "The Keepers of Names",
      "description": "Archivists who hold the original records and answer to no counting-house. They are neutral and slow, and they honor only requests made in the correct form.",
      "location_ids": ["loc_archive_of_quiet_names"]
    },
    {
      "id": "fac_order_of_the_scale",
      "name": "The Order of the Scale",
      "description": "The solemn attendants of the Weigher, who prepare each soul's finished ledger for judgment. They insist that the weighing proceed on schedule, because delay is itself a kind of injustice.",
      "location_ids": ["loc_hall_of_the_scales"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_return",
      "statement": "The dead cannot return to life. Only their accounts move between columns, houses, and ledgers.",
      "category": "metaphysics"
    },
    {
      "id": "rul_weighing_is_final",
      "statement": "Once a soul is weighed in the Hall of the Scales, its ledger is sealed and can never be amended.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ink_binds",
      "statement": "Anything written in funeral-ash ink becomes true for the soul it names, so a wrong entry harms that soul until it is formally struck and rewritten.",
      "category": "physics"
    },
    {
      "id": "rul_correction_chain",
      "statement": "A correction must be countersigned by an officer of each counting-house, in order, from the Scriptorium to the Hall of the Scales.",
      "category": "social"
    },
    {
      "id": "rul_seniority_of_stamps",
      "statement": "A senior stamp overrules a junior signature, but a junior scribe may file a correction in her own name without a sponsor.",
      "category": "social"
    },
    {
      "id": "rul_no_lies_in_the_archive",
      "statement": "No false statement can be entered in the Archive of Quiet Names. Ink refuses to dry on a lie.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_founding_of_the_exchequer",
      "name": "The Founding of the Exchequer",
      "description": "The first dead overflowed the old, informal judgment. The Weigher then ordered every soul recorded in a ledger so that no account could be lost or disputed.",
      "era": "The First Tally",
      "location_ids": ["loc_gate_of_entries", "loc_hall_of_the_scales"]
    },
    {
      "id": "evt_the_column_schism",
      "name": "The Column Schism",
      "description": "The Auditors of Debt and the Guild of Scribes quarreled over which ledger column recorded a soul's true worth. The dispute produced the present system of separate columns and a long mutual distrust.",
      "era": "The Age of Columns",
      "location_ids": ["loc_counting_house_of_debts", "loc_scriptorium_of_ash"]
    },
    {
      "id": "evt_the_sealed_drawer_affair",
      "name": "The Sealed Drawer Affair",
      "description": "A famed correction was buried when a senior auditor ordered an archive drawer sealed. The Keepers of Names have refused such orders ever since.",
      "era": "The Age of Columns",
      "location_ids": ["loc_archive_of_quiet_names"]
    },
    {
      "id": "evt_the_misfiled_soul",
      "name": "The Misfiled Soul",
      "description": "In the Scriptorium of Ash, a mortal soul was entered in the wrong ledger column during a hurried night shift. The error went unnoticed until a junior scribe found it just before the weighing.",
      "era": "The Present Season",
      "location_ids": ["loc_scriptorium_of_ash"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_correction_versus_pride",
      "name": "Correction Versus Pride",
      "description": "The junior scribe's correction would expose a senior auditor's earlier error. The Auditors of Debt want it quietly lost, while the Guild of Scribes fears blame for a mistake made on its watch.",
      "faction_ids": ["fac_guild_of_scribes", "fac_auditors_of_debt"]
    },
    {
      "id": "cnf_schedule_versus_truth",
      "name": "Schedule Versus Truth",
      "description": "The Order of the Scale will not delay the weighing, even for a valid correction. The Keepers of Names will release proof only through slow, formal channels. Together they leave the scribe too little time to prove her case.",
      "faction_ids": ["fac_order_of_the_scale", "fac_keepers_of_names"]
    }
  ]
}

