{
  "world_id": "wld_when_the_wind_turns",
  "name": "The Port of Sambhar Kotha",
  "description": "Sambhar Kotha is a fictional pre-industrial trade port on the Indian Ocean rim, set in the early sixteenth century. Its fortunes depend on the monsoon. The southwest winds carry ships east and north from late spring. Then the wind turns, the sea closes to deep-water sailing, and the season is lost. Three foreign envoys have each paid court to the harbour's rulers and each claims the first sailing slot. That slot goes to the cargo that reaches distant markets before the others, so it carries enormous profit and prestige. The protagonist is a harbour scribe, keeper of the tally-rolls and tide-ledgers. She must weigh contracts, bribes, old debts and half-forgotten customs, and settle the rival claims before the wind turns. The tone is sumptuous and tense. Cardamom smoke hangs over the quays, lacquered ships ride at anchor, silk and pepper change hands, and every delay brings the end of the season closer. All technology is pre-industrial: sail, oar, ink, wax seal, lamp, and signal fire.",
  "locations": [
    {
      "id": "loc_scribes_hall",
      "name": "The Hall of Tally-Rolls",
      "description": "A cool, shuttered building of carved teak beside the harbour office. Palm-leaf and paper ledgers of every ship, cargo, tide and debt are kept here. The scribes' guild arbitrates disputes here under the harbour master's seal."
    },
    {
      "id": "loc_pepper_quay",
      "name": "Pepper Quay",
      "description": "The main wharf, crowded with porters, brokers, and godowns reeking of pepper, cloves and tar. Ships are loaded here in order of their assigned slots. Tempers run hot as the season shortens."
    },
    {
      "id": "loc_envoys_caravanserai",
      "name": "The House of Three Courtyards",
      "description": "A walled guesthouse with three separate courtyards, where the foreign envoys are lodged apart so they cannot easily intrigue against one another. Fountains, spice-scented banquets and whispered bargains fill its rooms."
    },
    {
      "id": "loc_wind_watch_tower",
      "name": "The Wind-Watch Tower",
      "description": "A whitewashed stone tower on the headland where the harbour's weather-readers watch cloud, swell and bird flight for the first signs that the monsoon is about to turn. Its signal fires and lamps tell the whole port how much time remains."
    }
  ],
  "factions": [
    {
      "id": "fac_harbour_scribes",
      "name": "Guild of Harbour Scribes",
      "description": "The neutral keepers of records and arbiters of berth rights, bound by oath to the harbour master. Their authority rests entirely on being seen as incorruptible.",
      "location_ids": ["loc_scribes_hall", "loc_pepper_quay"]
    },
    {
      "id": "fac_gujarati_factors",
      "name": "Envoy of the Gujarat Merchant Houses",
      "description": "A smooth, wealthy envoy backed by banking families. He claims the first slot by right of long custom and pays with letters of credit honoured across the ocean.",
      "location_ids": ["loc_envoys_caravanserai", "loc_pepper_quay"]
    },
    {
      "id": "fac_ming_treasure_agent",
      "name": "Envoy of the Eastern Court",
      "description": "A formal envoy of a distant empire, carrying tribute goods and a sealed decree. He argues that a diplomatic cargo cannot be made to wait behind private merchants.",
      "location_ids": ["loc_envoys_caravanserai"]
    },
    {
      "id": "fac_red_sea_pilgrim_fleet",
      "name": "Envoy of the Red Sea Pilgrim Fleet",
      "description": "A devout and stubborn envoy whose ship must sail first to carry pilgrims and trade goods to the holy cities before the sea closes. He appeals to religious duty and to the harbour's reputation.",
      "location_ids": ["loc_envoys_caravanserai", "loc_wind_watch_tower"]
    },
    {
      "id": "fac_weather_readers",
      "name": "The Weather-Readers",
      "description": "A secretive hereditary caste of sailors who read winds and swells. Their forecasts decide how long the port can wait, and each envoy tries to court or coerce them.",
      "location_ids": ["loc_wind_watch_tower"]
    }
  ],
  "rules": [
    {
      "id": "rul_monsoon_cycle",
      "statement": "The monsoon winds blow from the southwest for a fixed season. Once they turn, deep-water sailing is too dangerous and no ship may leave until the following year.",
      "category": "physics"
    },
    {
      "id": "rul_one_first_slot",
      "statement": "Only one ship may hold the first sailing slot. Its cargo reaches market early and commands the highest prices.",
      "category": "social"
    },
    {
